function Button({ children, variant = 'primary', className = '', ...props }) {
  const styles = {
    primary: 'bg-violet-500 text-white shadow-lg shadow-violet-900/20 hover:bg-violet-400',
    secondary: 'border hairline bg-white/[.04] text-zinc-200 hover:bg-white/[.08]',
    ghost: 'text-zinc-400 hover:bg-white/[.06] hover:text-zinc-100',
    danger: 'border border-red-400/20 bg-red-400/10 text-red-300 hover:bg-red-400/15',
  }
  return <button className={`inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2 text-xs font-medium transition ${styles[variant]} ${className}`} {...props}>{children}</button>
}

function Badge({ children, color = 'purple' }) {
  const colors = { purple: 'border-violet-400/20 bg-violet-400/10 text-violet-300', green: 'border-emerald-400/20 bg-emerald-400/10 text-emerald-300', amber: 'border-amber-400/20 bg-amber-400/10 text-amber-300', gray: 'border-white/10 bg-white/[.04] text-zinc-400' }
  return <span className={`inline-flex items-center gap-1 rounded-full border px-2 py-1 text-[10px] font-medium ${colors[color]}`}>{children}</span>
}

function SectionHeading({ eyebrow, title, description, action }) {
  return <div className="mb-7 flex items-end justify-between gap-4">
    <div><p className="eyebrow mb-2">{eyebrow}</p><h1 className="text-2xl font-semibold tracking-tight text-zinc-100 sm:text-3xl">{title}</h1>{description && <p className="mt-2 max-w-xl text-sm leading-6 text-zinc-500">{description}</p>}</div>
    {action}
  </div>
}

function Avatar({ name = 'A', src, size = 'md' }) {
  const sizeClass = size === 'sm' ? 'h-7 w-7 text-[10px]' : 'h-9 w-9 text-xs'
  return src ? <img src={src} alt="" className={`${sizeClass} rounded-full object-cover ring-1 ring-white/10`} /> : <div className={`${sizeClass} grid place-items-center rounded-full bg-gradient-to-br from-violet-400 to-fuchsia-500 font-semibold text-white`}>{name.slice(0, 1).toUpperCase()}</div>
}

